<template>
	<view class="page">
		<view class="header-row">
			<view class="title">{{ titleMap[type] || '健康数据' }}</view>
			<view class="filters">
				<picker mode="selector" :range="rangeOptions" :value="rangeIndex" @change="onRangeChange">
					<view class="picker-display">{{ rangeOptions[rangeIndex] }}</view>
				</picker>
			</view>
		</view>

		<view class="tabs">
			<view :class="['tab', viewMode==='day'?'active':'']" @click="switchMode('day')">日</view>
			<view :class="['tab', viewMode==='week'?'active':'']" @click="switchMode('week')">周</view>
			<view :class="['tab', viewMode==='month'?'active':'']" @click="switchMode('month')">月</view>
			<view :class="['tab', viewMode==='year'?'active':'']" @click="switchMode('year')">年</view>
		</view>

		<qiun-data-charts type="line" :chartData="chartData" :opts="chartOpts" />

		<view class="legend">
			<text class="lg">用户ID：{{ userId }}</text>
			<text class="lg">设备：{{ deviceSummary || '全部' }}</text>
		</view>
	</view>
</template>

<script>
import uCharts from '../../uni_modules/qiun-data-charts/js_sdk/u-charts/config-echarts.js'
export default {
	data(){
		return {
			userId: '',
			type: 'heart_rate',
			rangeOptions: ['-1d','-7d','-30d','-365d'],
			rangeIndex: 0,
			viewMode: 'year',
			chartData: { categories: [], series: [{ name: '数值', data: [] }] },
			chartOpts: { legend: { show: true }, xAxis: { disableGrid: false }, yAxis: {} },
			deviceSummary: ''
		}
	},
	onLoad(query){
		this.userId = query.user_id || ''
		this.type = query.type || 'heart_rate'
		uni.setNavigationBarTitle({ title: this.titleMap[this.type] || '健康数据' })
		this.fetchData()
	},
	computed:{
		titleMap(){
			return { heart_rate: '心率', temperature: '体温', blood_oxygen: '血氧饱和度' }
		}
	},
	methods:{
		onRangeChange(e){
			this.rangeIndex = Number(e.detail.value)
			this.fetchData()
		},
		switchMode(mode){
			this.viewMode = mode
			this.rebuildXAxis()
		},
		rebuildXAxis(){
			// 固定刻度
			let categories = []
			if (this.viewMode==='day') categories = ['00:00','06:00','12:00','18:00']
			else if (this.viewMode==='week') categories = ['一','二','三','四','五','六','日']
			else if (this.viewMode==='month') categories = ['1','5','10','15','20','25','30']
			else categories = ['1','3','5','7','9','11']
			this.chartData.categories = categories
		},
		async fetchData(){
			try{
				const res = await uni.request({
					url: `${this.getBackendBase()}/api/health/user`,
					method: 'POST',
					data: { user_id: this.userId, time_range: this.rangeOptions[this.rangeIndex], fields: this.type },
					timeout: 10000
				})
				const data = res[1]?.data || res.data
				const arr = Array.isArray(data?.user_data) ? data.user_data : (data?.user_data ? [data.user_data] : [])
				const points = arr.filter(it => (it.field||it.filed)===this.type)
				// 简单按先后排序
				points.sort((a,b)=> new Date(a.timestamp||a.datetime||a.record_time||0) - new Date(b.timestamp||b.datetime||b.record_time||0))
				this.deviceSummary = Array.from(new Set(points.map(p=>`${p.device_id||'-'}(${p.device_name||'-'})`))).join(', ')
				this.rebuildXAxis()
				this.chartData.series = [{ name: '数值', data: points.map(p=>Number(p.value)) }]
			}catch(e){
				this.chartData = { categories: [], series: [{ name:'数值', data: [] }] }
			}
		},
		getBackendBase(){ return 'http://localhost:3000' }
	}
}
</script>

<style>
	.page { padding: 24rpx 32rpx; background: #fff; }
	.header-row { display: flex; align-items: center; }
	.title { font-size: 40rpx; font-weight: 700; color: #111; }
	.filters { margin-left: auto; }
	.picker-display { padding: 8rpx 16rpx; border: 1rpx solid #e5e5e5; border-radius: 8rpx; color: #333; font-size: 24rpx; }
	.tabs { margin-top: 20rpx; display: flex; gap: 16rpx; }
	.tab { padding: 10rpx 20rpx; border-radius: 30rpx; border: 1rpx solid #ddd; color: #555; }
	.tab.active { background: #111; color: #fff; border-color: #111; }
	.legend { margin-top: 20rpx; color: #8F98A3; font-size: 24rpx; display: flex; gap: 20rpx; }
</style>

